package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReaderBasedJsonParser#getTokenLocation
 */
public class ReaderBasedJsonParser_getTokenLocation_TriageGen1Test {

    private IOContext ioContext;
    private ObjectCodec codec;
    private String inputSource;

    @Before
    public void setUp() {
        ioContext = mock(IOContext.class);
        codec = mock(ObjectCodec.class);
        inputSource = "{\"key\": \"value\"}";
        when(ioContext.getSourceReference()).thenReturn(inputSource);
    }

    @Test
    public void testGetTokenLocationReturnsCorrectValues() throws Exception {
        // Using a real ReaderBasedJsonParser via a StringReader to ensure internal state is valid
        // We use a simple JSON string to trigger token parsing
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(inputSource),
                codec,
                null
        );

        // Move to the first token (the START_OBJECT '{')
        JsonToken token = parser.nextToken();
        Assert.assertEquals(JsonToken.START_OBJECT, token);

        // Get the location
        JsonLocation location = parser.getTokenLocation();

        // Verify properties
        // Note: getTokenCharacterOffset, getTokenLineNr, and getTokenColumnNr are internal 
        // but we verify the resulting JsonLocation object matches the parser's state.
        Assert.assertNotNull(location);
        Assert.assertEquals(inputSource, location.getSourceRef());
        Assert.assertEquals(-1L, location.getByteOffset());

        // Verify that the location components are non-negative and consistent with a valid parse
        Assert.assertTrue("Line number should be >= 1", location.getLineNr() >= 1);
        Assert.assertTrue("Column number should be >= 1", location.getColumnNr() >= 1);
        Assert.assertTrue("Character offset should be >= 0", location.getCharOffset() >= 0);
    }

    @Test
    public void testGetTokenLocationAfterMovingToField() throws Exception {
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(inputSource),
                codec,
                null
        );

        // Move to START_OBJECT
        parser.nextToken(); 
        // Move to FIELD_NAME ("key")
        parser.nextToken();

        JsonLocation location = parser.getTokenLocation();

        Assert.assertNotNull(location);
        Assert.assertEquals(inputSource, location.getSourceRef());

        // The location should have advanced from the start of the object
        Assert.assertTrue(location.getCharOffset() > 0);
    }

    @Test
    public void testGetTokenLocationWithNullSource() throws Exception {
        // Test behavior when source reference is null
        when(ioContext.getSourceReference()).thenReturn(null);

        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(inputSource),
                codec,
                null
        );

        parser.nextToken();
        JsonLocation location = parser.getTokenLocation();

        Assert.assertNotNull(location);
        Assert.assertNull(location.getSourceRef());
    }
}
